import{_ as i,a0 as l,w as u,s as m,I as e,x as o,a1 as r,A as p,ao as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"如何使用Tmux提高終端環境下的效率 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用Tmux提高終端環境下的效率 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用Tmux提高終端環境下的效率 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用Tmux提高終端環境下的效率 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140811 How to improve your productivity in terminal environment with Tmux","title":"如何使用Tmux提高終端環境下的效率","tag":"201410","desc":""},"relativePath":"201410/20140811 How to improve your productivity in terminal environment with Tmux.md","filePath":"[post].md"}'),a={name:"201410/20140811 How to improve your productivity in terminal environment with Tmux.md"};function d(x,t,T,g,f,b){const n=l("Link");return u(),m("div",null,[t[23]||(t[23]=e("h1",{id:"如何使用tmux提高終端環境下的效率",tabindex:"-1"},[o("如何使用Tmux提高終端環境下的效率 "),e("a",{class:"header-anchor",href:"#如何使用tmux提高終端環境下的效率","aria-label":"Permalink to “如何使用Tmux提高終端環境下的效率”"},"​")],-1)),t[24]||(t[24]=e("p",null,"鼠標的發明是了不起的創新，它讓電腦更加接近普通人。但從程序員和系統管理員的角度，使用電腦工作時，手一旦離開鍵盤，就會有些分心。",-1)),t[25]||(t[25]=e("p",null,"作為一名系統管理員，我大量的工作都需要在終端環境下。打開很多標籤，然後在多個終端之間切換窗口會讓我慢下來。尤其是當我的服務器出問題的時候，我不能浪費任何時間！",-1)),t[26]||(t[26]=e("p",null,[e("img",{src:"https://farm6.staticflickr.com/5563/14853747084_e14cf18e8f_z.jpg",alt:""})],-1)),e("p",null,[r(n,{href:"http://tmux.sourceforge.net/"},{default:p(()=>[...t[0]||(t[0]=[o("Tmux",-1)])]),_:1}),t[1]||(t[1]=o("是我日常工作必要的工具之一。我可以藉助Tmux構建出複雜的開發環境，同時還可以在一旁進行SSH遠程連接。我可以開出很多窗口，將其拆分成很多面板，接管和分離會話等等。掌握了Tmux之後，你就可以扔掉鼠標了（只是個玩笑:D）。",-1))]),t[27]||(t[27]=s(`<p>Tmux（&quot;Terminal Multiplexer&quot;的簡稱）可以讓我們在單個屏幕的靈活佈局下開出很多終端，我們就可以協作地使用它們。舉個例子，在一個面板中，我們用Vim修改一些配置文件，在另一個面板，我們使用<code>irssi</code>聊天，而在其餘的面板，可以跟蹤一些日誌。然後，我們還可以打開新的窗口來升級系統，再開一個新窗口來進行服務器的ssh連接。在這些窗口面板間瀏覽切換和創建它們一樣簡單。它的高度可配置和可定製的，讓其成為你心中的延伸</p><h3 id="在linux-osx下安裝tmux" tabindex="-1">在Linux/OSX下安裝Tmux <a class="header-anchor" href="#在linux-osx下安裝tmux" aria-label="Permalink to “在Linux/OSX下安裝Tmux”">​</a></h3><p>你可以通過編譯軟件源或者通過系統包管理器的方式安裝，我建議使用包管理器，這樣比編譯更快更簡單</p><h4 id="osx" tabindex="-1">OSX: <a class="header-anchor" href="#osx" aria-label="Permalink to “OSX:”">​</a></h4><pre><code># sudo brew install tmux
# sudo port install tmux
</code></pre><h4 id="debian-ubuntu" tabindex="-1">Debian/Ubuntu: <a class="header-anchor" href="#debian-ubuntu" aria-label="Permalink to “Debian/Ubuntu:”">​</a></h4><pre><code># sudo apt-get install tmux
</code></pre>`,7)),e("p",null,[t[3]||(t[3]=o("####RHEL/CentOS/Fedora(RHEL/CentOS 要求 ",-1)),r(n,{href:"http://xmodulo.com/2013/03/how-to-set-up-epel-repository-on-centos.html"},{default:p(()=>[...t[2]||(t[2]=[o("EPEL repo",-1)])]),_:1}),t[4]||(t[4]=o("):####",-1))]),t[28]||(t[28]=s(`<pre><code>$ sudo yum install tmux
</code></pre><p>####Archlinux:####</p><pre><code>$ sudo pacman -S tmux
</code></pre><h3 id="使用不同會話工作" tabindex="-1">使用不同會話工作 <a class="header-anchor" href="#使用不同會話工作" aria-label="Permalink to “使用不同會話工作”">​</a></h3><p>使用Tmux的最好方式是使用會話的方式，這樣你就可以以你想要的方式，將任務和應用組織到不同的會話中。如果你想改變一個會話，會話裏面的任何工作都無須停止或者殺掉。讓我們來看看這是怎麼工作的。</p><p>讓我們開始一個叫做&quot;session&quot;的會話，並且運行top命令</p><pre><code>$ tmux new -s new session
$ top
</code></pre><p>然後輸入<strong>CTRL-b d</strong>從此會話脱離，想要重新連接此會話，需輸入：</p><pre><code>$ tmux attach-session -t session
</code></pre><p>之後你會看到top操作仍然運行在重新連接的會話上。</p><p>一些管理sessions的命令：</p><pre><code>$ tmux list-session
$ tmux new-session &lt;會話名&gt;
$ tmux attach-session -t &lt;會話名&gt;
$ tmux rename-session -t &lt;會話名&gt;
$ tmux choose-session -t &lt;會話名&gt;
$ tmux kill-session -t &lt;會話名&gt;
</code></pre><h3 id="使用不同的窗口工作" tabindex="-1">使用不同的窗口工作 <a class="header-anchor" href="#使用不同的窗口工作" aria-label="Permalink to “使用不同的窗口工作”">​</a></h3><p>很多情況下，你需要在一個會話中運行多個命令，執行多個任務。我們可以在一個會話的多個窗口裏組織他們。在現代的GUI終端（比如 iTerm或者Konsole），一個窗口被視為一個標籤。在會話中配置了我們默認的環境之後，我們就能夠在一個會話中創建許多我們需要的窗口。窗口就像運行在會話中的應用程序，當我們脱離當前會話的時候，它仍在持續，讓我們來看一個例子：</p><pre><code>$ tmux new -s my_session
</code></pre><p><img src="https://farm6.staticflickr.com/5583/14853747014_442b3742fa_z.jpg" alt=""></p><p>按下<strong>CTRL-b c</strong></p><p>這將會創建一個新的窗口，然後屏幕的光標移向它。現在你就可以在新窗口下運行你的新應用。你可以修改你當前窗口的名字。在目前的例子裏，我運行的top程序，所以top就是該窗口的名字</p><p>如果你想要重命名，只需要按下：</p><p><strong>CTRL-b</strong></p><p>狀態條將會改變，這時你將可以重命名當前的窗口</p><p><img src="https://farm6.staticflickr.com/5579/14855868482_d52516a357_z.jpg" alt=""></p><p>一旦在一個會話中創建多個窗口，我們需要在這些窗口間移動的辦法。窗口像數組一樣組織在一起，從0開始用數字標記每個窗口，想要快速跳轉到其餘窗口：</p><p><strong>CTRL-b &lt;窗口號&gt;</strong></p><p>如果我們給窗口起了名字，我們可以使用下面的命令找到它們：</p><p><strong>CTRL-b f</strong></p><p>也可以列出所有窗口：</p><p><strong>CTRL-b w</strong></p><p>按照順序切換到不同的窗口：</p><p><strong>CTRL-b n</strong>（到達下一個窗口） <strong>CTRL-b p</strong>（到達上一個窗口）</p><p>想要離開一個窗口，可以輸入 exit 或者：</p><p><strong>CTRL-b &amp;</strong></p><p>關閉窗口之前，你需要確認一下。</p><h3 id="把窗口分成許多面板" tabindex="-1">把窗口分成許多面板 <a class="header-anchor" href="#把窗口分成許多面板" aria-label="Permalink to “把窗口分成許多面板”">​</a></h3><p>有時候你在編輯器工作的同時，需要查看日誌文件。在編輯的同時追蹤日誌真的很有幫助。Tmux可以讓我們把窗口分成許多面板。舉個例子，我們可以創建一個控制台監測我們的服務器，同時用編輯器構造複雜的開發環境，這樣就能同時進行編譯和調試了。</p><p>讓我們創建另一個Tmux會話，讓其以面板的方式工作。首先，如果我們在某個會話中，那就從Tmux會話中脱離出來：</p><p><strong>CTRL-b d</strong></p><p>開始一個叫做&quot;panes&quot;的新會話：</p><pre><code>$ tmux new -s panes
</code></pre><p>你可以水平或者豎直分割一個窗口，水平分割輸入：</p><p><strong>CRTL-b &quot;</strong></p><p>現在你就擁有兩個面板，現在我們豎直分割：</p><p><strong>CRTL-b %</strong></p><p>又增加了兩個：</p><p><img src="https://farm4.staticflickr.com/3881/14669677417_bc1bdce255_z.jpg" alt=""></p><p>在他們之間移動：</p><p><strong>CTRL-b &lt;光標鍵&gt;</strong></p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3>`,48)),e("p",null,[t[7]||(t[7]=o("我希望這篇教程能對你有作用。此外，像",-1)),r(n,{href:"https://github.com/tmuxinator/tmuxinator"},{default:p(()=>[...t[5]||(t[5]=[o("Tmuxinator",-1)])]),_:1}),t[8]||(t[8]=o(" 或者 ",-1)),r(n,{href:"https://github.com/jimeh/tmuxifier"},{default:p(()=>[...t[6]||(t[6]=[o("Tmuxifier",-1)])]),_:1}),t[9]||(t[9]=o("這樣的工具，可以簡化Tmux會話，窗口和麪板的創建及加載，你可以很容易就配置Tmux。如果你沒有使用過這些，嘗試一下吧！",-1))]),t[29]||(t[29]=e("hr",null,null,-1)),e("p",null,[t[11]||(t[11]=o("via: ",-1)),r(n,{href:"http://xmodulo.com/2014/08/improve-productivity-terminal-environment-tmux.html"},{default:p(()=>[...t[10]||(t[10]=[o("http://xmodulo.com/2014/08/improve-productivity-terminal-environment-tmux.html",-1)])]),_:1})]),e("p",null,[t[15]||(t[15]=o("作者：",-1)),r(n,{href:"http://xmodulo.com/author/valerio"},{default:p(()=>[...t[12]||(t[12]=[o("Christopher Valerio",-1)])]),_:1}),t[16]||(t[16]=o(" 譯者：",-1)),r(n,{href:"https://github.com/su-kaiyao"},{default:p(()=>[...t[13]||(t[13]=[o("su-kaiyao",-1)])]),_:1}),t[17]||(t[17]=o(" 校對：",-1)),r(n,{href:"https://github.com/wxy"},{default:p(()=>[...t[14]||(t[14]=[o("wxy",-1)])]),_:1})]),e("p",null,[t[20]||(t[20]=o("本文由 ",-1)),r(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[18]||(t[18]=[o("LCTT",-1)])]),_:1}),t[21]||(t[21]=o(" 原創翻譯，",-1)),r(n,{href:"http://linux.cn/"},{default:p(()=>[...t[19]||(t[19]=[o("Linux中國",-1)])]),_:1}),t[22]||(t[22]=o(" 榮譽推出",-1))])])}const v=i(a,[["render",d]]);export{L as __pageData,v as default};
